            $json['matchingTransactions']        = $this->matchingTransactions;
        }
        if (isset($this->matchingValues)) {
            $json['matchingValues']              = $this->matchingValues;
        }
        if (isset($this->mccs)) {
            $json['mccs']                        = $this->mccs;
        }
        if (isset($this->merchantNames)) {
            $json['merchantNames']               = $this->merchantNames;
        }
        if (isset($this->merchants)) {
            $json['merchants']                   = $this->merchants;
        }
        if (isset($this->processingTypes)) {
            $json['processingTypes']             = $this->processingTypes;
        }
        if (isset($this->riskScores)) {
            $json['riskScores']                  = $this->riskScores;
        }
        if (isset($this->sameAmountRestriction)) {
            $json['sameAmountRestriction']       = $this->sameAmountRestriction;
        }
        if (isset($this->sameCounterpartyRestriction)) {
            $json['sameCounterpartyRestriction'] = $this->sameCounterpartyRestriction;
        }
        if (isset($this->sourceAccountTypes)) {
            $json['sourceAccountTypes']          = $this->sourceAccountTypes;
        }
        if (isset($this->timeOfDay)) {
            $json['timeOfDay']                   = $this->timeOfDay;
        }
        if (isset($this->tokenRequestors)) {
            $json['tokenRequestors']             = $this->tokenRequestors;
        }
        if (isset($this->totalAmount)) {
            $json['totalAmount']                 = $this->totalAmount;
        }
        if (isset($this->walletProviderAccountScore)) {
            $json['walletProviderAccountScore']  = $this->walletProviderAccountScore;
        }
        if (isset($this->walletProviderDeviceScore)) {
            $json['walletProviderDeviceScore']   = $this->walletProviderDeviceScore;
        }
        if (isset($this->walletProviderDeviceType)) {
            $json['walletProviderDeviceType']    = $this->walletProviderDeviceType;
        }

        return (!$asArrayWhenEmpty && empty($json)) ? new stdClass() : $json;
    }
}
